<script>
  import Element from "./elements/index.svelte";
  export let onSetLoad;
  export let eventType;
  let rewardList = [];

  onSetLoad(true);
  const updateLoad = (json) => {
    onSetLoad(false);

    rewardList = JSON.parse(json);
  };

  import { addListernEvent } from "api/functions";
  addListernEvent("table.tasks."+eventType, updateLoad);
</script>

<div class="mg-task-rewards">
  {#each rewardList as item}
    <Element {item} />
  {/each}
</div>