<script>
    import { translateText } from 'lang'
    import { onInputFocus, onInputBlur } from "@/views/player/menu/elements/fractions/data.js";
    import { setPopup } from "../../data";
    import { executeClientToGroup, executeClientAsyncToGroup } from "api/rage";
    import { format } from 'api/formatter'

    export let departments;
    export let onSelectDepartment;
    export let onDepartmentDelete;
    
    let searchText = ""
    const filterCheck = (elText, text) => {
        if (!text || !text.length)
            return true;

        text = text.toUpperCase();

        if (elText.toString().toUpperCase().includes(text))
            return true;

        return false;
    }


    

    const onCreateCallback = (name, tag) => {
        let check = format("rank", name);
        if (!check.valid) {
            window.notificationAdd(4, 9, check.text, 3000);
            return;
        }

        check = format("tag", tag);
        if (!check.valid) {
            window.notificationAdd(4, 9, check.text, 3000);
            return;
        }

        executeClientToGroup('createDepartment', name, tag)
    }

    const onCreate = () => {
        setPopup ("Input", {
            headerTitle: "Create Squad",
            headerIcon: "fractionsicon-squads",
            inputs: [
                {
                    title: "Squad Name",
                    placeholder: "Enter new name",
                    maxLength: 36,
                },
                {
                    title: "Squad Tag",
                    placeholder: "Enter squad tag",
                    maxLength: 5
                }
            ],
            button: translateText('popups', 'Подтвердить'),
            callback: onCreateCallback
        })
    }

    let settings = {};
    const getSettings = () => {
        executeClientAsyncToGroup("getSettings").then((result) => {
            if (result && typeof result === "string")
                settings = JSON.parse(result);
        });
    }
    getSettings();

    let selectItem = false;
     const onUpdateCallback = (name, tag) => {
        let check = format("rank", name);
        if (!check.valid) {
            window.notificationAdd(4, 9, check.text, 3000);
            return;
        }

        check = format("tag", tag);
        if (!check.valid) {
            window.notificationAdd(4, 9, check.text, 3000);
            return;
        }

        executeClientToGroup('updateDepartment', selectItem.id, name, tag);
    }

    const onUpdate = (item) => {
        selectItem = item;
        setPopup ("Input", {
            headerTitle: "Edit Squad Information",
            headerIcon: "fractionsicon-squads",
            inputs: [
                {
                    title: "Squad Name",
                    placeholder: "Please enter the new name",
                    maxLength: 36,
                    value: item.name
                },
                {
                    title: "Squad Tag",
                    placeholder: "Please enter the squad tag",
                    maxLength: 5,
                    value: item.tag
                }
            ],
            button: translateText('popups', 'Подтвердить'),
            callback: onUpdateCallback
        });
    }
</script>
<div class="fractions__content">
    <div class="box-between pr-22 pl-8 pr-226">
        <div class="fractions__scroll_element p-20 pb-10">
            <div class="fractions_stats_title fs-14 name mr-16">{translateText('player1', 'Название')}</div>
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Начальник')}</div>
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Тег отряда')}</div>
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Участники')}</div>
            <div class="fractions_stats_title fs-14 name">Actions</div>
        </div>
    </div>
    <div class="fractions__main_scroll h-t-box">
        {#each departments.filter(el => filterCheck(el.name, searchText)) as item}
            <div class="fractions__scroll_element hover p-20">
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.name}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.chiefName}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">#{item.tag}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.playerCount} person.</div>
                
                <div class="fractions_stats_title fs-14 name whitecolor m-0">
                    <div class="box-around">
                        {#if settings.createDepartment}
                        <div class="tindericons-edit" title="Edit squad" on:click={() => onUpdate (item)}></div>
                        {/if}
                        <div class="fractionsicon-upgrade" title="Manage squad" on:click={() => onSelectDepartment (item)}></div>
                        {#if settings.deleteDepartment}
                            <div class="fractionsicon-fired" title="Delete squad"  on:click={() => onDepartmentDelete (item)}></div>
                        {/if}
                    </div>
                </div>
            </div>
        {/each}
    </div> 
    <div class="box-between pr-22 ptr-22">
        <div class="fractions__scroll_element footer p-20">
            {#if settings.createDepartment}
            <div class="mg-menu-btn" on:click={onCreate}>
                <span class="fractionsicon-plus"></span>
                {translateText('player1', 'Создать отряд')}
            </div>
            {/if}
            <div class="item member-search">
                <input on:focus={onInputFocus} on:blur={onInputBlur} type="text" name="search" bind:value={searchText} placeholder="Search rank name"/>
                <div class="fractionsicon-loop"></div>
            </div>
        </div>
    </div>    
</div>