<script>
    import { translateText } from 'lang'
    import { executeClientToGroup, executeClientAsyncToGroup } from 'api/rage'
    import { onInputFocus, onInputBlur } from "@/views/player/menu/elements/fractions/data.js";
    executeClientToGroup('vehiclesLoad')

    let isVehicleUpdateRank = true;
    let isSellVehicle = true;
    let vehicles = [];

    const getVehicles = (_isVehicleUpdateRank, _vehicles, _isSellVehicle) => {
        isVehicleUpdateRank = _isVehicleUpdateRank;
        isSellVehicle = _isSellVehicle;

        if (_vehicles && typeof _vehicles === "string")
            vehicles = JSON.parse(_vehicles);

    }

    import { addListernEvent } from "api/functions";
    import { onUpdateRank, setPopup } from "../../data";

    addListernEvent ("table.vehicles", getVehicles)


    let carNumber;
    const onEvacuationCallback = () => {
        executeClientToGroup('evacuation', carNumber);
    }

    const onEvacuation = (number) => {
        carNumber = number;
        setPopup ("Confirm", {
            headerTitle: "Recalling a vehicle",
            text: `You really want to recall this car No: '${number}'?`,
            button: 'Recall',
            callback: onEvacuationCallback
        })
    }
    const onGps = (number) => {
        executeClientToGroup('gps', number);
    }

    const onSellCar = (number) => {
        executeClientToGroup('sellCar', number);
    }
let searchText = ""
    const filterCheck = (elText, text) => {
        if (!text || !text.length)
            return true;

        text = text.toUpperCase();

        if (elText.toString().toUpperCase().includes(text))
            return true;

        return false;
    };
</script>
<div class="fractions__content">
    <div class="box-between pr-22 pl-8 pr-226">
        <div class="fractions__scroll_element p-20 pb-10">
            <div class="fractions_stats_title fs-14 name small">#</div>
            <div class="fractions_stats_title fs-14 name">Model & Number</div>
            <div class="fractions_stats_title fs-14 name">Rank</div>
            <div class="fractions_stats_title fs-14 name" style="text-align: center;">Status</div>
            <div class="fractions_stats_title fs-14 name small" style="text-align: center;">Actions</div>
        </div>
    </div>

    <div class="fractions__main_scroll h-t-box">
        {#each vehicles.filter(el => filterCheck(el.model, searchText) || filterCheck(el.number, searchText)) as item, index}
            <div class="fractions__scroll_element hover p-20">
                <div class="fractions_stats_title fs-14 name whitecolor m-0 small">{index+1}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.model} [ {item.number} ]</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.rankName}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">
                    <div class="box-around">
                        {#if item.isEvacuation}
                            <div on:click={() => onEvacuation(item.number)} class="">Recall</div>
                        {/if}
                        {#if item.isGps}
                            <div on:click={() => onGps(item.number)} class="">Mark in GPS</div>
                        {/if}
                    </div>
                </div>

                <div class="fractions_stats_title fs-14 name whitecolor m-0 small">
                    <div class="box-around">
                        {#if isVehicleUpdateRank}
                        <div class="fractionsicon-settings" on:click={() => onUpdateRank("List of ranks", "fractionsicon-parking", "Choose the rank from which this transport will be accessible.", 'updateVehicleRank', item.number)}></div>
                        {/if}
                        <!-- {#if isSellVehicle}
                            <div class="fractionsicon-fired" on:click={() => onSellCar(item.number)}></div>
                        {/if} -->
                    </div>
                </div>
            </div>
        {/each}
    </div>   
    <div class="box-between pr-22 ptr-22">
        <div class="fractions__scroll_element footer p-20">
            <div class="item member-search">
                <input on:focus={onInputFocus} on:blur={onInputBlur} type="text" name="search" bind:value={searchText} placeholder="Search model or number"/>
                <div class="fractionsicon-loop"></div>
            </div>
        </div>
    </div> 
</div>