<script>
    import { translateText } from 'lang'
    import { executeClientToGroup } from 'api/rage'
    import { onInputFocus, onInputBlur } from "@/views/player/menu/elements/fractions/data.js";
    import { format } from 'api/formatter'
    import { setPopup } from "../../data";

    export let settings;
    export let onSettings;

    let searchText = ""
    const filterCheck = (elText, text) => {
        if (!text || !text.length)
            return true;

        text = text.toUpperCase();

        if (elText.toString().toUpperCase().includes(text))
            return true;

        return false;
    }
    let selectRank = null

    const onSelectRank = (item = null) => {
        selectRank = item
    }

    $: if (settings) {
        if (selectRank) {
            const index = settings.ranks.findIndex(a => a.id === selectRank.id)

            if (settings.ranks [index])
                onSelectRank(settings.ranks [index])
        }
    }

    let selectItem = null;

    const onUpdateRankNameCallback = (rankName) => {
        let check = format("rank", rankName);
        if (!check.valid) {
            window.notificationAdd(4, 9, check.text, 3000);
            return;
        }
        executeClientToGroup("updateDepartmentRankName", settings.id, selectItem.id, rankName);
    };

    const onEditRankName = (item) => {
        selectItem = item;
        setPopup("Input", {
            headerTitle: "Edit Rank Name",
            headerIcon: "fractionsicon-squads",
            inputs: [
                {
                    title: "Rank Name",
                    placeholder: "Enter new name",
                    maxLength: 36,
                    value: item.name
                }
            ],
            button: 'Edit',
            callback: onUpdateRankNameCallback
        });
    };

</script>

<div class="fractions__content">
    <div class="box-between pr-22 pl-8 pr-226">
        <div class="fractions__scroll_element p-20 pb-10">
            <div class="fractions_stats_title fs-14 name mr-16">{translateText('player1', 'Ранг')}</div>
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Название')}</div>
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Участники')}</div>
            <div class="fractions_stats_title fs-14 name small">Actions</div>
        </div>
    </div>
    <div class="fractions__main_scroll h-t-box">
        {#each settings.ranks.filter(el => filterCheck(el.name, searchText)) as item, index}
            <div class="fractions__scroll_element hover p-20">
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.id}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.name}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.playerCount} people.</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0 small">
                    <div class="box-around">
                        <div class="tindericons-edit" title="Edit squad rank"   on:click={() => onEditRankName (item)}></div>
                    </div>
                </div>
            </div>
        {/each}
    </div> 
    <div class="box-between pr-22 ptr-22">
        <div class="fractions__scroll_element footer p-20">
            <div class="box-between gap">
                <div class="mg-menu-btn" on:click={() =>onSettings()}>&#x2190;</div>
            </div>
            <div class="item member-search">
                <input on:focus={onInputFocus} on:blur={onInputBlur} type="text" name="search" bind:value={searchText} placeholder="Search..."/>
                <div class="fractionsicon-loop"></div>
            </div>
        </div>
    </div>    
</div>