<script>
    import { translateText } from 'lang'
    import { onInputFocus, onInputBlur } from "@/views/player/menu/elements/fractions/data.js";
    import { executeClientToGroup } from "api/rage";
    import {setPopup} from "../../data";

    export let departmentId;
    export let members;
    export let ranks;
    export let onSquadRanks;
    export let settings;
    export let onSelectDepartment;
    export let onSettings;
    export let department;

    


    let searchText = ""
    const filterCheck = (elText, text) => {
        if (!text || !text.length)
            return true;

        text = text.toUpperCase();

        if (elText.toString().toUpperCase().includes(text))
            return true;

        return false;
    }

    let deletePlayerUUid = 0;
    const onPlayerDeleteCallback = () => {
        executeClientToGroup("deletePlayerDepartment", departmentId, deletePlayerUUid)
    }

    const onDepartmentDelete = (item) => {
        deletePlayerUUid = item.uuid;
        setPopup ("Confirm", {
            headerTitle: "Remove from Squad",
        headerIcon: "fractionsicon-members",
        text: `Are you sure you want to remove ${item.name} from the squad?`,
        button: 'Remove',
            callback: onPlayerDeleteCallback
        })
    };

</script>
<div class="fractions__content">
    <div class="box-between pr-22 pl-8 pr-226">
        <div class="fractions__scroll_element p-20 pb-10">
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Имя Фамилия')}</div>
        <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Ранг')}</div>
        <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Отряд')}</div>
        <div class="fractions_stats_title fs-14 name">Position</div>
        <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Очки')}</div>
            <div class="fractions_stats_title fs-14 name small">Actions</div>
        </div>
    </div>
    <div class="fractions__main_scroll h-t-box">
        {#each members.filter(el => filterCheck(el.name, searchText)) as item}
            <div class="fractions__scroll_element hover p-20">
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.name}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.rankName}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{ranks[item.departmentRank].name}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{department.chief === item.name?'Squad Leader':department.zam1 === item.name?'Deputy #1':department.zam2 === item.name?'Deputy #2':'Participation'}</div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0">{item.score}</div>
                
                <div class="fractions_stats_title fs-14 name whitecolor m-0 small">
                    <div class="box-around">
                        <div class="fractionsicon-fired" title="Remove user from squad"  on:click={() => onDepartmentDelete (item)}></div>
                    </div>
                </div>
            </div>
        {/each}
    </div> 
    <div class="box-between pr-22 ptr-22">
        <div class="fractions__scroll_element footer p-20">
            <div class="box-between gap">
                <div class="mg-menu-btn" on:click={() =>onSelectDepartment()}>&#x2190;</div>
                {#if settings.isLeader}
                    <div class="mg-menu-btn no-bg" on:click={() => onSettings (department)}><span class="fractionsicon-settings"></span> {translateText('player1', 'Настройки')}</div>
                {/if}
                {#if settings.isLeader || department.myRank === 3}
                    <div class="mg-menu-btn no-bg" on:click={onSquadRanks}><div class="fractionsicon-plus"></div> Assign</div>
                {/if}
            </div>
            <div class="item member-search">
                <input on:focus={onInputFocus} on:blur={onInputBlur} type="text" name="search" bind:value={searchText} placeholder="Search member..."/>
                <div class="fractionsicon-loop"></div>
            </div>
        </div>
    </div>    
</div>