<script>
    import { fly } from 'svelte/transition';
    
    let kills = [];
    window.kill = {
        show: (killName, Icon, Name, kColor, vColor) => {
            kills.unshift({
                killName: killName,
                Icon: Icon,
                Name: Name,
                killerColor: kColor,
                victimColor: vColor
            });
            
            if (kills.length > 4) kills.splice(5, 1);
            kills = kills;
        },
        clear: () => {
            kills = [];
            kills = kills;
        }
    }
</script>
<div class="killlist">
    {#each kills as item, index}
        <div class="block">
            {#if item.killName.length > 2}
                <div class="left" style="color: {item.killerColor}">{item.killName}</div>
            {/if}
            <div class="center">
                {#if item.Icon.length > 2}
                    <div class="{item.Icon}"/>
                {:else}
                    <div class="hudevoicon-skull"/>
                {/if}
            </div>
            <div class="right" style="color: {item.victimColor}">{item.Name}</div>
        </div>
    {/each}
</div>
