<script>
  import { translateText } from "lang";
  // import Settings from './elements/settings.svelte'
  // import News from './elements/news.svelte'
  // import Stock from './elements/stock.svelte'

  // import { setTableType, selectTableView, setView, selectPopup, setPopup, isFraction, onInputBlur } from './data'
  import { setPopup, isOrganization, isFraction } from "../../data";
  // import Upgrade from "../../popups/upgrade/index.svelte";
  import { charFractionID } from "store/chars";
  import { format } from "api/formatter";
  import { executeClientToGroup, executeClientAsyncToGroup } from "api/rage";

  // export let isOrgUpgrate;
  export let isLoad;
  export let settings;
  export let tableInfo;
  export let leader;
  export let onlineData;
  export let stats;

  // const onUpgrade = () => {
  //     setPopup ("Upgrade");
  // };
  // const onSetLoad = (toggled) => {
  //     isLoad = toggled;
  // };

  let stock = {};

  const getStock = () => {
    executeClientAsyncToGroup("getStock").then((result) => {
      if (result && typeof result === "string") stock = JSON.parse(result);
    });
  };
  getStock();

  import { addListernEvent } from "api/functions";
  addListernEvent("table.isStock", getStock);

  const updateGunStock = () => {
    executeClientToGroup("updateGunStock");
  };

  const updateStock = () => {
    executeClientToGroup("updateStock");
  };

  // -------------------------------------------------------------------------
  import { charUUID } from "store/chars";
  let board = {};
  let selectPage = 1;

  const getBoard = () => {
    executeClientAsyncToGroup("getBoard").then((result) => {
      if (result && typeof result === "string") {
        board = JSON.parse(result);

        selectPage = board.page;
      }
    });
  };
  getBoard();

  addListernEvent("table.board", getBoard);

  const onAddBoard = (title, text) => {
    if (!title.length || title.length >= 20) return;
    else if (!text.length || text.length >= 100) return;

    executeClientToGroup("addBoard", title, text);
  };

  const addBoard = () => {
    setPopup("Input", {
      headerTitle: "Write a news article",
      headerIcon: "fractionsicon-news",
      inputs: [
        {
          title: "Enter News Title",
          placeholder: "Enter News Title",
          maxLength: 20,
        },
        {
          title: "Please provide the news text.",
          placeholder: "Please provide the news text.",
          maxLength: 100,
          textarea: true,
        },
      ],
      button: translateText("popups", "Подтвердить"),
      callback: onAddBoard,
    });
  };

  const onUpdateBoard = (title, text) => {
    if (!title.length || title.length >= 20) return;
    else if (!text.length || text.length >= 100) return;

    executeClientToGroup("updateBoard", board.page, title, text);
  };

  const updateBoard = () => {
    setPopup("Input", {
      headerTitle: "Edit the news",
      headerIcon: "fractionsicon-news",
      inputs: [
        {
          title: "Fresh News Title",
          placeholder: "Latest News Update",
          maxLength: 20,
          value: board.title,
        },
        {
          title: "New Text of the News",
          placeholder: "Enter a new text",
          maxLength: 100,
          textarea: true,
          value: board.text,
        },
      ],
      button: translateText("popups", "Подтвердить"),
      callback: onUpdateBoard,
    });
  };

  const deleteBoard = () => {
    executeClientToGroup("deleteBoard", board.page);
  };

  // -----------------------------------------------------------------------------------------

  const onEvacuationCallback = (type) => {
    executeClientToGroup("evacuation.all", type);
  };

  const onEvacuation = () => {
    setPopup("List", {
      // headerIcon: "fractionsicon-parking",
      headerTitle: "Recall vehicle",
      list: [
        { id: 0, name: "Without fuel" },
        { id: 1, name: "With fuel" },
      ],
      button: "Recall",
      callback: onEvacuationCallback,
    });
  };

  const onConfirmCallback = () => {
    executeClientToGroup("bonus");
  };

  const openConfirmPopup = () => {
    setPopup("Confirm", {
      headerTitle: "Are you sure?",
      text: "This action is irreversible. Do you want to continue?",
      button: "Yes, Confirm",
      callback: onConfirmCallback,
    });
  };

  $: cloud =
    document.cloud +
    ($charFractionID > 0 && isFraction()
      ? `img/fractionLogo/Fraction_${$charFractionID}.png`
      : `img/fractionLogo/Org.png`);
  $: leaderName =
    leader && leader.name ? leader.name.replace(/_/g, " ") : "Loading...";
</script>

{#if isLoad}
  <div class="fractions__content">
    <div class="main-box">
      <div class="main-grid">
        <div class="main-flex mt-0 center">
          <div class="mg-m-logo">
            <img class="fractions__lead_photo" src={cloud} alt="" />
          </div>
        </div>
        <div class="main-flex mt-0 space-between">
          <div class="mg-m-online">
            {onlineData.online || 0} / {onlineData.all || 50} Online
          </div>
          <div class="mg-m-frac-name">{tableInfo.name}</div>
          <div class="mg-m-frac-l-des">{leaderName}</div>
        </div>
        <div class="main-flex">
          <div class="main-flex-item">
            <div class="i-title">{translateText("player1", "Материалы")}</div>
            <div class="i-title">{stats.mats} / {stats.maxMats}</div>
          </div>
          <div class="main-flex-item">
            <div class="i-title">{translateText("player1", "Деньги")}</div>
            <div class="i-title">${format("money", stats.money)}</div>
          </div>
          {#if $charFractionID < 6}
            <div class="main-flex-item">
              <div class="i-title">{translateText("player1", "Наркотики")}</div>
              <div class="i-title">{stats.drugs} PCS</div>
            </div>
          {/if}
          {#if stats.warZonesCount >= 0}
            <div class="main-flex-item">
              <div class="i-title">Territories:</div>
              <div class="i-title">{stats.warZonesCount}</div>
            </div>
          {/if}
          {#if stats.gangZonesCount >= 0}
            <div class="main-flex-item">
              <div class="i-title">Territories:</div>
              <div class="i-title">{stats.gangZonesCount}</div>
            </div>
          {/if}

          {#if $charFractionID > 5}
            <div class="main-flex-item">
              <div class="i-title">{translateText("player1", "Аптечки")}</div>
              <div class="i-title">{stats.medKits} PC.</div>
            </div>
          {/if}

          {#if stats.bizCount >= 0}
            <div class="main-flex-item">
              <div class="i-title">Businesses:</div>
              <div class="i-title">{stats.bizCount}</div>
            </div>
          {/if}
          {#if stock.isGunAccessStock}
            <div class="main-flex-item hover" on:click={updateGunStock}>
              <div class="i-title">Warehouse</div>
              <div class="i-title">
                {#if stock.isGunStock}
                  <div class="status-o">Opened</div>
                {:else}
                  <div class="status-c">Closed</div>
                {/if}
              </div>
            </div>
          {/if}
          {#if stock.isAccessStock}
            <div class="main-flex-item hover" on:click={updateStock}>
              <div class="i-title">Composition</div>
              <div class="i-title">
                {#if stock.isStock}
                  <div class="status-o">
                    {translateText("player1", "Разрешён")}
                  </div>
                {:else}
                  <div class="status-c">
                    {translateText("player1", "Запрещён")}
                  </div>
                {/if}
              </div>
            </div>
          {/if}
        </div>
        <div class="main-flex mt-0">
          <div
            class="main-flex-footer"
            class:hover={!settings.tableWall}
            on:click={settings.tableWall ? addBoard : null}
          >
            {#if board.count > 0}
              <div class="news-box">
                {#if board.uuid === $charUUID || (typeof board.uuid !== "undefined" && settings.editAllTabletWall)}
                  <div class="cross" on:click|stopPropagation={deleteBoard}>
                    X
                  </div>
                {/if}
                <div class="position">Message from the {board.rankName}</div>
                <div class="desc">{board.text}</div>
                <div class="author">- {board.name}</div>
              </div>
            {:else}
              <div class="fractions__stats_subtitle box-center gray wh-100">
                {translateText("player1", "Новостей пока нет.")}
              </div>
            {/if}
          </div>
          <div class="small">
            <div class="main-flex-item small hover" on:click={openConfirmPopup}>
              <div class="i-title">Issue bonus</div>
            </div>
            <div
              class="main-flex-item small last hover"
              on:click={onEvacuation}
            >
              <div class="i-title">Recall cars</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
  <!-- <div class="fractions__header">
     <div class="box-flex">
         <div class="box-column">
             <div class="box-flex">
                 <span class="fractionsicon-fractions"></span>
                 <div class="fractions__header_title">{translateText('player1', 'Главная страница')}</div>
             </div>
             <div class="fractions__header_subtitle">General information, news and log of actions</div>
         </div>
     </div>
     {#if isOrgUpgrate}
         <div class="fractions__main_button" on:click={onUpgrade}>{translateText('player1', 'Улучшения')}</div>
     {/if}
 </div>
 <div class="fractions__content">
     <div class="box-between">
         <Stock />
     </div>
     <div class="box-between not-center mt-20">
         <div class="box-column">
             {#if isOrganization()}
                 <Settings {settings} />
                 <News {settings} />
             {:else}
                 <News {settings} />
             {/if}
         </div>
     </div>
 </div> -->
{/if}
