<script>
    import { translateText } from 'lang'
    import { executeClientToGroup } from 'api/rage'
    executeClientToGroup('clothesLoad')


let clothes = [];


    const getClothes = (_clothes) => {
        clothes = JSON.parse(_clothes);
    }

    import { addListernEvent } from "api/functions";

    addListernEvent ("table.clothes", getClothes)

    import { setPopup, onUpdateRank } from "../../data";


    let selectForm = {}
    let newFormName = ""

    const updateRank = (rank) => {
        executeClientToGroup("clothesUpdate", selectForm.name, newFormName, rank, selectForm.gender);
    }

    const onEditFormCallback = (value) => {
        newFormName = value
        onUpdateRank("List of ranks", "fractionsicon-form", "Choose the rank from which the form will be accessible..", null, null, updateRank);
    }

    const onEditForm = (item) => {
        selectForm = item
        setPopup ("Input", {
            headerTitle: "1",
            headerIcon: "fractionsicon-form",
            input: {
                title: "Form Name",
                placeholder: "Enter the name of the form.",
                maxLength: 36,
                value: selectForm.name
            },
            button: translateText('popups', 'Подтвердить'),
            callback: onEditFormCallback
        })
    }
</script>
<div class="fractions__content">
    <div class="fractions__main_scroll h-t-box split">
        {#each clothes as item, index}
            <div class="fractions__scroll_element split hover p-20">
                <div class="fractions_stats_title fs-14 name whitecolor m-0">
                    <div class="box-column box-i">
                        <div class="fractions__black_title">{item.name} {#if item.gender}<span class='male'> (M)</span>{:else}<span class='female'> (F)</span>{/if}</div>
                        <div class="fractions__black_title gray mb-18">{item.rankName}</div>
                    </div>
                </div>
                <div class="fractions_stats_title fs-14 name whitecolor m-0 small" on:click={() => onEditForm(item)}><span class="tindericons-edit"></span> Edit</div>
            </div>
        {/each}
    </div>  
</div>