<script>
    import { translateText } from 'lang'
    import {executeClientAsyncToGroup} from "api/rage";
    import { onInputFocus, onInputBlur } from "@/views/player/menu/elements/fractions/data.js";
    import { charUUID } from 'store/chars';

    import moment from 'moment';
    let isLog = false;
    executeClientAsyncToGroup("isLog").then((result) => {
        isLog = result;
    });
    let logType = 0;

    let searchText = "";
    const onGetLogs = (index) => {
        if (index !== 0 && !isLog)
            return;

        if (logType === index)
            return;

        logType = index;

        if (!searchText)
            searchText = "";

        if (index === 1)
            getLog (-1, false, searchText, 0)
        else if (index === 0)
            getLog ($charUUID, false, searchText, 0)
        else if (index === 2)
            getLog (-1, true, searchText, 0)
    }

    let logs = []
    const getLogs = () => {
        executeClientAsyncToGroup("getLogs").then((result) => {
            if (result && typeof result === "string")
                logs = JSON.parse(result);
        });
    }

    getLogs();

    import { addListernEvent } from "api/functions";
    import {getLog} from "../../data";
    addListernEvent ("table.logs", getLogs)

    const HandleKeyDown = (event) => {
        const { keyCode } = event;
        if (keyCode == 13 && searchText && searchText.length >= 1) {
            onGetLogs ()
            searchText = ""
        }
    }

</script>

<svelte:window on:keyup={HandleKeyDown} />

<div class="fractions__content">
    <div class="box-between pr-22 pl-8 pr-226">
        <div class="fractions__scroll_element p-20 pb-10">
            {#if logs && logs[0] && logs[0].uuid}
                <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Имя')}</div>
                <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Ранг')}</div>
            {/if}
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Действие')}</div>
            <div class="fractions_stats_title fs-14 name">{translateText('player1', 'Дата')}</div>
        </div>
    </div>

    <div class="fractions__main_scroll h-t-box">
        {#if logs && logs.length}
            {#each logs as log}
                <div class="fractions__scroll_element hover p-20">
                    {#if log.uuid}
                        <div class="fractions_stats_title fs-14 name whitecolor m-0">{log.name}</div>
                        <div class="fractions_stats_title fs-14 name whitecolor m-0">{log.rankName}</div>
                    {/if}
                    <div class="fractions_stats_title fs-14 name whitecolor m-0">{log.text}</div>
                    <div class="fractions_stats_title fs-14 name whitecolor m-0">{moment(log.time).format('MMM DD, YYYY')} <span>{moment(log.time).format('HH:mm')}</span></div>
                </div>
            {/each}
        {:else}
            <div class="fractions_stats_title fs-14 name whitecolor m-0 text-center">
                {translateText('player1', 'Никаких действий не замечено!')}
            </div>
        {/if}
    </div> 
    <div class="box-between pr-22 ptr-22">
        <div class="fractions__scroll_element footer p-20">
            <div class="box-flex">
                <div class="fractions__selector no-m-bot" class:active={logType === 0}  on:click={() => onGetLogs (0)}>
                    {translateText('player1', 'Личный')}
                </div>
                <div class="fractions__selector no-m-bot" class:active={logType === 1} on:click={() => onGetLogs (1)}>
                    {translateText('player1', 'Общий')}
                </div>
                <div class="fractions__selector no-m-bot" class:active={logType === 2}  on:click={() => onGetLogs (2)}>
                    {translateText('player1', 'Склад')}
                </div>
            </div>
            <div class="item member-search">
                <input on:focus={onInputFocus} on:blur={onInputBlur} type="text" name="search" bind:value={searchText} placeholder={translateText('player1', 'Поиск..')}/>
                <div class="fractionsicon-loop"></div>
            </div>
        </div>
    </div> 
</div>