<script>
    import { isPopupBuyOpened } from '../../stores.js'
    import { format } from 'api/formatter'
    import { accountRedBucks } from 'store/account'
    import { executeClientToGroup, executeClientAsyncToGroup} from 'api/rage'

    const pricePremium = 50;

    let isPremium = 0;
    executeClientAsyncToGroup("getPremium").then((result) => {
        isPremium = result;
    });

    const onBuyPremium = () => {
        if (isPremium)
            return;
        else if (!window.loaderData.delay ("battlePass.onBuyPremium", 1))
            return;

        executeClientToGroup ("buyPremium");

        onClose ();
    }

    const onClose = () => isPopupBuyOpened.set(false);
</script>

<div class="battlepass__popup_info popupback">
    <div class="newproject__buttonblock" on:keypress={() => {}} on:click={onClose}>
        <div class="newproject__button">ESC</div>
        <div>Close</div>
    </div>
    <div class="battlepass__popup_maintitle">Unlock a Cyber pass</div>
    <div class="battlepass__popup_buytext">
        By acquiring a premium transplant, you also get the opportunity to get a bunch of unique prizes in addition to the usual pass.
        <br>
        <br>
        Prizes received from the premium can be taken from the post office.You can buy a premium transplant in any period of the season.Every season this option is zeroing.
    </div>
    <div class="box-flex">
        <div class="battlepass__popup_pricetext">Purchase of the SC</div>
        <div class="battlepass__button" on:keypress={() => {}} on:click={onBuyPremium}>Unlock</div>
    </div>
    <div class="battlepass__popup_heroes"></div>
</div>